import React, { useEffect, useRef, useState } from "react";
import CanvasJSReact from "@canvasjs/react-charts";

const { CanvasJSChart } = CanvasJSReact;

const BarChart = () => {
    const chartRef = useRef(null);
    const [chartData, setChartData] = useState(null);

    useEffect(() => {
      const fetchData = async () => {
        try {
          const response = await fetch("http://localhost:5206/api/BloodRL/predict");
          if (response.ok) {
            const data = await response.json();
            setChartData(data);
          } else {
            console.error("Failed to fetch data:", response.status, response.statusText);
          }
        } catch (error) {
          console.error("An error occurred while fetching data:", error);
        }
      };

      fetchData();
    }, []);

    return (
      <div>
        {chartData && (
          <CanvasJSChart
            options={{
              animationEnabled: true,
              theme: "dark2",
              title: {
                text: "Blood Availability",
              },
              axisY: {
                title: "Actual Availability",
                scaleBreaks: {
                  autoCalculate: true,
                  type: "wavy",
                  lineColor: "white",
                },
              },
              data: Object.values(chartData).map((hospitalData) => ({
                type: "column",
                indexLabel: "{y}",
                indexLabelFontColor: "white",
                dataPoints: Object.values(hospitalData).map((item) => ({
                  label: `${item.hospitalName} - ${item.bloodGroup}`,
                  y: item.actualAvailability,
                  predictedAvailability: item.predictedAvailability,
                })),
              })),
            }}
          />
        )}
      </div>
    );
  };

  export default BarChart;
